const inp = $input.first().json;
const fmt = d => d.toISOString().slice(0,10);
const toG = d => d.replace(/-/g,'/');
const yest = new Date(Date.now()-86400000);
const today = new Date();
const rawS = inp.start_date ? String(inp.start_date).trim().slice(0,10) : '';
const rawE = inp.end_date   ? String(inp.end_date).trim().slice(0,10)   : '';
const s = rawS || fmt(yest);
const e = rawE || fmt(today);
// gmail_before = end_date + 1 day (exclusive upper bound)
// This means "May 3 only" → gmail_after=May3 before=May4 → correct
const eNextDay = fmt(new Date(new Date(e+'T00:00:00').getTime() + 86400000));
const category = (inp.category && String(inp.category).trim()) ? String(inp.category).trim() : 'All';
const author   = (inp.author   && String(inp.author).trim()  ) ? String(inp.author).trim()   : 'All';
return [{json:{
  source:'form',command:'/summarize',chat_id:'8641228015',
  start_date:s,end_date:e,
  gmail_after:toG(s),gmail_before:toG(eNextDay),
  category:category,author:author
}}];

// n8n Data Table API returns {data: [...rows]}
const rows = $input.first().json.data || [];
if (rows.length === 0) return [{ json: { _empty: true } }];
return rows.map(row => ({ json: row }));

const vals=$input.first().json.values||[];
if(vals.length<2) return [{json:{seen_ids:[]}}];
const ids=vals.slice(1).map(r=>String(r[0]||'').trim()).filter(id=>id.length>0);
return [{json:{seen_ids:ids}}];

const all=$input.all();
const senders=all.filter(i=>i.json.sender_query && i.json.sender_query!=='__no_match__');
const dedupItem=all.find(i=>Array.isArray(i.json.seen_ids));
const seenIds=dedupItem?dedupItem.json.seen_ids:[];
let dateInfo={};
try{dateInfo=$('Set Date Range').first().json;}catch(e){}
const ga=dateInfo.gmail_after||'',gb=dateInfo.gmail_before||'';
const cid=dateInfo.chat_id||'8641228015';
// If no real senders (all filtered out), return empty → Aggregate fires with 0 items
if(senders.length===0) return [];
return senders.map(s=>({json:{
  sender_query:s.json.sender_query||'',
  display_name:s.json.display_name||'',
  category_hint:s.json.category_hint||'',
  gmail_after:ga,gmail_before:gb,chat_id:cid,seen_ids:seenIds
}}));

const seen=new Set(($('Build Dedup Array').first().json.seen_ids||[]).map(String));
const newItems=$input.all().filter(it=>!seen.has(String(it.json.id)));
if(newItems.length>0) return newItems;
// All emails already summarised — pass a sentinel to trigger the cached path
return [{json:{_all_cached:true}}];

return $input.all().map(item => {
  const it = item.json;
  // simple:false → html/text fields; simple:true (legacy) → body.content/snippet
  let raw = it.html || it.text || it.body?.content || it.snippet || '';

  // Extract "view online" URL BEFORE stripping — tightened to avoid unsubscribe/tracking URLs
  const viewOnlineRe = /<a[^>]+href=["']([^"']{10,})["'][^>]*>([\s\S]{0,200}?)<\/a>/gi;
  let viewOnlineUrl = '';
  let m;
  while ((m = viewOnlineRe.exec(raw)) !== null) {
    const href = m[1];
    const hrefLower = href.toLowerCase();
    const txt = m[2].replace(/<[^>]+>/g,'').toLowerCase().trim();
    // Must contain clear "view online / read in browser" text
    if (!/view.{0,20}(?:online|browser|web)|read.{0,10}browser|web version/.test(txt)) continue;
    // Must NOT be an unsubscribe, tracking, or utility link
    if (/unsubscribe|unsub|optout|opt.out|manage|preferences|privacy|tracking|link\.mail\.|t\.co\/|click\.|redirect/.test(hrefLower)) continue;
    viewOnlineUrl = href;
    break;
  }

  let b = raw
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi,' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi,' ')
    .replace(/<[^>]+>/g,' ')
    .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ').replace(/&quot;/g,'"')
    .replace(/\s+/g,' ').trim().slice(0,12000);

  return {json:{...it, clean_body:b, view_online_url:viewOnlineUrl}};
});

const originals = $('Strip HTML').all();
return $input.all().map((item, index) => {
  const it = item.json;
  const orig = originals[index]?.json || {};
  let parsed;
  try {
    const raw = it.message?.content || (it.choices && it.choices[0]?.message?.content) || '{}';
    parsed = JSON.parse(raw);
  } catch(e) {
    return {json:{error:true, error_msg:e.message, subject:orig.subject||orig.Subject||'', gmail_message_id:orig.id||''}};
  }
  const msgId = orig.id || '';

  // Date: always prefer the email's actual date (reliable) over LLM-extracted date
  let date = '';
  if (orig.date) {
    // simple:false gives ISO string
    const d = new Date(orig.date);
    if (!isNaN(d.getTime()) && d.getFullYear() > 1971) {
      date = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
    }
  }
  if (!date && orig.internalDate) {
    // simple:true (legacy) gave epoch ms
    const d = new Date(parseInt(orig.internalDate));
    if (!isNaN(d.getTime()) && d.getFullYear() > 1971) {
      date = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
    }
  }
  // Fall back to LLM date only if we couldn't get a valid one above
  if (!date) date = parsed.date || '';

  // Author: simple:false gives from.value[0].name; simple:true gave From string
  let authorFallback = '';
  if (orig.from) {
    if (typeof orig.from === 'string') {
      authorFallback = orig.from.split('<')[0].trim().replace(/^"(.*)"$/, '$1');
    } else if (orig.from.value && orig.from.value[0]) {
      const f = orig.from.value[0];
      authorFallback = f.name || f.address || '';
    } else if (orig.from.text) {
      authorFallback = orig.from.text.split('<')[0].trim().replace(/^"(.*)"$/, '$1');
    }
  } else if (orig.From) {
    authorFallback = orig.From.split('<')[0].trim().replace(/^"(.*)"$/, '$1');
  }

  // Subject
  const subject = orig.subject || orig.Subject || parsed.subject || '';

  // Link: LLM first, then view_online_url fallback — but filter out obviously bad links
  let llmLink = (parsed.substack_or_web_link || '').trim();
  let fallbackLink = (orig.view_online_url || '').trim();

  const isBadLink = (url) => {
    if (!url) return true;
    const u = url.toLowerCase();
    return /unsubscribe|unsub|optout|opt.out|manage|preferences|disclosures|privacy\.html|tracking|link\.mail\.|t\.co\/|click\.|redirect/.test(u);
  };

  if (isBadLink(llmLink)) llmLink = '';
  if (isBadLink(fallbackLink)) fallbackLink = '';
  const webLink = llmLink || fallbackLink;

  return {json:{
    ...parsed,
    author_name: parsed.author_name || authorFallback,
    date: date,
    gmail_message_id: msgId,
    gmail_link: 'https://mail.google.com/mail/u/0/#inbox/' + msgId,
    subject: subject,
    category_hint: orig.category_hint || '',
    substack_or_web_link: webLink
  }};
});

const ORDER=['Emerging Tech','Product Principles and Building','PM Interview Prep','Personal Finance','Other'];
const cid='8641228015';

// New summaries from Aggregate (via this node's direct input)
const newSummaries=($input.first().json.summaries||[]).filter(s=>!s.error&&!s._all_cached);

// Cached summaries from Read Summaries Log (columns: [id,date,category,author,subject,summary,link])
const dateInfo=$('Set Date Range').first().json;
const startDate=new Date(dateInfo.start_date+'T00:00:00');
const endDate  =new Date(dateInfo.end_date  +'T23:59:59');
const catFilter   =String(dateInfo.category||'All').trim();
const authorFilter=String(dateInfo.author  ||'All').trim();
const allRows=($('Read Summaries Log').first().json.values||[]).slice(1);
const cachedSummaries=allRows.filter(r=>{
  if(!r[0]) return false;
  const d=new Date(r[1]||'');
  if(isNaN(d.getTime())||d<startDate||d>endDate) return false;
  if(catFilter!=='All'&&catFilter!==''){
    if(String(r[2]||'').trim().toLowerCase()!==catFilter.toLowerCase()) return false;
  }
  if(authorFilter!=='All'&&authorFilter!==''){
    if(!String(r[3]||'').trim().toLowerCase().includes(authorFilter.toLowerCase())) return false;
  }
  return true;
}).map(r=>({
  gmail_message_id:r[0]||'',
  date:r[1]||'',
  category:r[2]||'Other',
  author_name:r[3]||'',
  subject:r[4]||'',
  summary_bullets:String(r[5]||'').split(' | ').filter(b=>b.trim()),
  substack_or_web_link:r[6]||'',
  gmail_link:r[0]?'https://mail.google.com/mail/u/0/#inbox/'+r[0]:'',
  worth_reading_in_full:false,
  reading_reason:'',
  _from_cache:true
}));

// Merge: new takes priority; dedup by gmail_message_id
const seenIds=new Set(newSummaries.map(s=>s.gmail_message_id).filter(Boolean));
const seenCacheIds=new Set();
const uniqueCached=cachedSummaries.filter(s=>{
  if(!s.gmail_message_id||seenIds.has(s.gmail_message_id)||seenCacheIds.has(s.gmail_message_id)) return false;
  seenCacheIds.add(s.gmail_message_id);
  return true;
});
const sums=[...newSummaries,...uniqueCached];

if(sums.length===0) return [{json:{message:'\u{1F4ED} No newsletters found for this date range.',chat_id:cid,summaries:[]}}];

const grp={};
for(const s of sums){const c=s.category||'Other';if(!grp[c])grp[c]=[];grp[c].push(s);}
const esc=t=>String(t||'').replace(/([_*[\]()~`>#+\-=|{}.!])/g,'\\$1');
const ds=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});
const HEADER='\u{1F4EC} *Newsletter Digest — '+esc(ds)+'*\n\n';
const MAX=3900;
const blocks=[];
for(const cat of ORDER){
  if(!grp[cat]) continue;
  let first=true;
  for(const s of grp[cat]){
    let blk='';
    if(first){blk+='*'+esc(cat)+'*\n';first=false;}
    blk+='\n\u{1F464} *'+esc(s.author_name||'Unknown')+'*';
    if(s.date) blk+=' · '+esc(s.date);
    if(s._from_cache) blk+=' \u{1F4BE}';
    blk+='\n';
    for(const b of(s.summary_bullets||[])) blk+='  • '+esc(b)+'\n';
    if(s.worth_reading_in_full&&s.reading_reason) blk+='\u{1F4D6} _'+esc(s.reading_reason)+'_\n';
    // Labeled links: article link (Substack/web) + Gmail app deep link
    function linkLabel(url){
      try{
        const h=new URL(url).hostname.replace(/^www\./,'');
        if(h.includes('substack.com')) return 'Read on Substack';
        if(h.includes('beehiiv.com'))  return 'Read on Beehiiv';
        if(h.includes('medium.com'))   return 'Read on Medium';
        if(h.includes('ghost.io')||h.includes('ghost.org')) return 'Read on Ghost';
        return 'Read on '+h;
      }catch(e){return 'Read online';}
    }
    let artLnk=s.substack_or_web_link||'';
    if(artLnk.includes('mail.google.com')) artLnk=''; // skip gmail web URLs — shown via deep link instead
    const gmLnk=s.gmail_message_id?'https://mail.google.com/mail/u/0/#inbox/'+s.gmail_message_id:'';
    const lparts=[];
    if(artLnk) lparts.push('['+esc(linkLabel(artLnk))+']('+artLnk+')');
    if(gmLnk)  lparts.push('[Open in Gmail]('+gmLnk+')');
    if(lparts.length) blk+=lparts.join(' · ')+'\n';
    blocks.push(blk);
  }
}
const msgs=[];
let cur=HEADER;
for(const blk of blocks){
  if(cur.length+blk.length>MAX&&cur!==HEADER){msgs.push(cur.trimEnd());cur=HEADER;}
  cur+=blk;
}
if(cur!==HEADER) msgs.push(cur.trimEnd());
if(msgs.length===0) msgs.push(HEADER+'No newsletters to show\.');
return msgs.map((msg,i)=>({json:{
  message:msgs.length>1?msg+'\n\n_Part '+(i+1)+' of '+msgs.length+'_':msg,
  chat_id:cid,
  summaries:i===0?sums:[]
}}));

const items = $input.all();
// Read filter values from Set Date Range (accessible anywhere in the execution tree)
const dateInfo = $('Set Date Range').first().json;
const catFilter    = String(dateInfo.category || 'All').trim();
const authorFilter = String(dateInfo.author   || 'All').trim();

const filtered = items.filter(item => {
  const senderCat  = String(item.json.category_hint || '').trim();
  const senderName = String(item.json.display_name  || '').trim();
  // Category filter (exact match, case-insensitive)
  if (catFilter !== 'All' && catFilter !== '') {
    if (senderCat.toLowerCase() !== catFilter.toLowerCase()) return false;
  }
  // Author filter (partial match, case-insensitive)
  if (authorFilter !== 'All' && authorFilter !== '') {
    if (!senderName.toLowerCase().includes(authorFilter.toLowerCase())) return false;
  }
  return true;
});

// If nothing matched, pass a sentinel so Aggregate still fires with 0 real results
if (filtered.length === 0) {
  return [{json:{_no_match:true, display_name:'', sender_query:'__no_match__', category_hint:'', gmail_after:'', gmail_before:'', seen_ids:[]}}];
}
return filtered;

const items=$input.all();
// If 0 items (all-new case: IF false fires with nothing) → don't trigger downstream
if(items.length===0) return [];
// Sentinel arrived: return empty summaries wrapper for Format Telegram
return [{json:{summaries:[],_all_cached:true}}];
